"""Identifiers: UUIDv7 generated by the application (DATABASE_SCHEMA.md §1)."""

from __future__ import annotations

import os
import time
from uuid import UUID

_MASK_48 = (1 << 48) - 1
_MASK_62 = (1 << 62) - 1


def new_id() -> UUID:
    """UUIDv7 (RFC 9562): 48-bit Unix time in milliseconds followed by 74 random bits.

    Time-ordered, so B-tree indexes on primary keys stay compact. Python 3.13 has no ``uuid.uuid7``.
    """
    unix_ms = time.time_ns() // 1_000_000
    random_bits = int.from_bytes(os.urandom(10), "big")  # 80 bits, 74 are used
    rand_a = (random_bits >> 68) & 0xFFF
    rand_b = random_bits & _MASK_62
    value = (unix_ms & _MASK_48) << 80 | 0x7 << 76 | rand_a << 64 | 0b10 << 62 | rand_b
    return UUID(int=value)
